import pandas as pd,numpy as np,glob
from scipy.optimize import least_squares
D={f:pd.read_csv(f).values[::5] for f in glob.glob('train/*.csv')}
def sim(p,d):
  Kp,Tw,Tp,Kq,Tq=p; t=d[:,0];P,Q,V,th,Vs=d[:,1:].T; dt=t[1]-t[0]
  x=th[0];pc=0;qc=0;Po=[];Qo=[]
  for i in range(len(t)):
    w=(th[i]-x)/Tw/(2*np.pi*60); Po.append(P[0]+pc);Qo.append(Q[0]+qc)
    x+=dt*(th[i]-x)/Tw; pc+=dt*(-Kp*w-pc)/Tp; qc+=dt*(Kq*(Vs[i]-V[i])-qc)/Tq
  return np.array(Po)-P,np.array(Qo)-Q
def res(p): return np.concatenate([np.concatenate(sim(p,d)) for d in D.values()])
r=least_squares(res,[17,.05,.2,20,.1],bounds=([0,.002,.002,0,.002],[100,2,5,200,5]))
print(r.x, np.sqrt(np.mean(r.fun**2)))
for f,d in D.items(): a,b=sim(r.x,d);print(f,np.std(a),np.std(d[:,1]),np.std(b),np.std(d[:,2]))

