    e=Vs[i]-vf; vf+=dt*(V[i]-vf)/Tv; qi+=dt*Ki*e; qc+=dt*(Kq*e+qi-qc)/Tq
  return Qo-Q
def rq(p): return np.concatenate([simq(p,d) for d in D.values()])
